// Local presentation interactions only; no commerce, identity or payment requests.
document.querySelector('[data-menu]')?.addEventListener('click',e=>{const b=e.currentTarget;const n=document.querySelector('.mobile-menu');const open=n.classList.toggle('open');b.setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('.mobile-menu')?.classList.contains('open');document.querySelector('.mobile-menu')?.classList.remove('open');document.querySelector('[data-menu]')?.setAttribute('aria-expanded','false');if(open)document.querySelector('[data-menu]')?.focus();}});
document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-state]').forEach(x=>{x.setAttribute('aria-pressed',String(x===b));x.classList.toggle('secondary',x!==b);});document.querySelectorAll('.state-only').forEach(x=>x.classList.toggle('active',x.id===b.dataset.state));}));
document.querySelectorAll('[data-quantity]').forEach(b=>b.addEventListener('click',()=>{const s=b.parentElement.querySelector('span');const v=Number(s.textContent)+Number(b.dataset.quantity);s.textContent=String(Math.max(1,Math.min(9,v)));s.title='Illustrative quantity only. Totals are the last-confirmed fixture.';}));
document.querySelectorAll('[data-demo-message]').forEach(b=>b.addEventListener('click',()=>{let n=document.querySelector('#prototype-status');if(!n){n=document.createElement('div');n.id='prototype-status';n.className='notice';n.setAttribute('role','status');b.after(n)}n.textContent='Visual prototype: this action needs its canonical server contract. No data was submitted.';}));
const params=new URLSearchParams(location.search);if(params.get('neutral')==='1')document.body.classList.add('neutral');
for(const im of document.querySelectorAll('main img'))im.addEventListener('error',()=>{const box=document.createElement('div');box.className='missing-media';box.setAttribute('role','img');box.setAttribute('aria-label','Image not supplied: '+im.alt);box.textContent='Image not supplied';im.replaceWith(box);});
